import { countLabel } from '@shinefold/studio/schema-types/preview/count-label/count-label';
import { defineField, defineType } from 'sanity';

const SET_BY_PIPELINE_DESCRIPTION = 'Set by the reading-depth pipeline.';

export const postTakeawaysSchema = defineType({
  name: 'postTakeaways',
  title: 'Takeaways',
  type: 'object',
  description:
    '30-second-skim content, generated by the reading-depth pipeline.',
  options: { collapsible: true, collapsed: true },
  fields: [
    defineField({
      name: 'takeaways',
      title: 'Takeaways',
      type: 'array',
      description: '3–7 short takeaways, each under 160 characters.',
      of: [{ type: 'string', validation: (rule) => rule.max(160) }],
      validation: (rule) => rule.min(3).max(7),
    }),
    defineField({
      name: 'generatedAt',
      title: 'Generated At',
      type: 'datetime',
      description: SET_BY_PIPELINE_DESCRIPTION,
      readOnly: true,
    }),
    defineField({
      name: 'model',
      title: 'Model',
      type: 'string',
      description: SET_BY_PIPELINE_DESCRIPTION,
      readOnly: true,
    }),
  ],
  preview: {
    select: { takeaways: 'takeaways' },
    prepare({ takeaways }: { takeaways?: string[] }) {
      return {
        title: 'Takeaways',
        subtitle: takeaways?.length
          ? countLabel(takeaways, 'takeaway')
          : 'No takeaways yet',
      };
    },
  },
});
